package cn.zhuatech.documentai.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class DocumentExtractionReleaseServiceTest{private final DocumentExtractionReleaseService s=new DocumentExtractionReleaseService();@Test void releasesGovernedExtraction(){var r=s.assess(new DocumentExtractionReleaseService.Request("T1",true,true,true,96,90,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(DocumentExtractionReleaseService.Decision.RELEASE);}@Test void pilotsOperationalGaps(){var r=s.assess(new DocumentExtractionReleaseService.Request("T2",true,true,true,96,90,true,true,true,true,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnsafeExtraction(){var r=s.assess(new DocumentExtractionReleaseService.Request("T3",false,false,false,60,90,false,false,false,false,true,true,false));assertThat(r.blockers()).hasSize(9);}}
